public sealed class ReintentoApiTests
{
    private const string PreguntaPromedio = "¿Cuál es mi promedio?";
    private const string PreguntaQ10Seis = "¿Qué estudiantes de mi programa tienen alguna asignatura perdida?";
    private const string PerdidaDeMateo = "Mateo Vargas perdió Estadística.";
    private const string PerdidasDeValentina = "Valentina Castro: Microeconomía (1.8) y Estadística (2.3).";
    private const int SalidaPorLlamada = 20;
    private const decimal ToleranciaDeCosto = 0.000001m;

    public static TheoryData<string, string> BloqueosSinReintento => new()
    {
        { "SEG-10b-nombre-ajeno", "Andres Martinez sacó 2.6 en Cálculo" },
        { "SEG-10b-id-inventado", "EST 099 tiene un promedio de 4.39." }
    };

    [Fact]
    [Trait("CA", "CA-21")]
    [Trait("ESC", "ESC-193")]
    [Trait("RF", "SEG-10c")]
    public async Task ESC_193b_El_reintento_se_entrega_con_los_tokens_y_el_costo_de_los_dos_turnos_y_reintento_true_en_la_auditoria()
    {
        var llm = GuionesPorTurno.Texto("Tu promedio es 4.40.", "Tu promedio es 4.39.");
        using var fabrica = new FabricaApi(llm: llm, configuracion: FabricaApi.Precios("0.10", "0.50"), conocimientoReal: true);

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", PreguntaPromedio);

        Assert.Equal(200, respuesta.Estado);
        Afirmaciones.SalidaDelContrato(respuesta);
        Assert.Equal("Tu promedio es 4.39.", respuesta.Respuesta);
        Assert.Equal(2, fabrica.Llm.Llamadas);
        var entrada = fabrica.Llm.Solicitudes.Sum(ConsumoRealista.Reportados);
        var salida = fabrica.Llm.Llamadas * SalidaPorLlamada;
        Assert.Equal(entrada + salida, respuesta.Tokens);
        Assert.InRange(respuesta.CostoUsd, ConsumoRealista.CostoDe(entrada, salida, 0.10m, 0.50m) - ToleranciaDeCosto, ConsumoRealista.CostoDe(entrada, salida, 0.10m, 0.50m) + ToleranciaDeCosto);
        Assert.True(respuesta.UsoDatosEstudiante);
        var evento = Assert.Single(fabrica.Auditoria.Eventos);
        Assert.Equal(ResultadoAuditoria.Respondida, evento.Resultado);
        Assert.Equal(entrada + salida, evento.Tokens);
        AfirmacionesDeReintento.AfirmarReintentoRegistrado(evento);
    }

    [Fact]
    [Trait("CA", "CA-21")]
    [Trait("ESC", "ESC-193")]
    [Trait("RF", "SEG-10f")]
    public async Task ESC_193a_El_coordinador_recibe_el_texto_del_reintento_con_un_solo_segundo_turno()
    {
        var llm = GuionesPorTurno.LeeElProgramaYResponde(PerdidaDeMateo, PerdidasDeValentina);
        using var fabrica = new FabricaApi(llm: llm, conocimientoReal: true);

        var respuesta = await fabrica.PreguntarCoordinadorAsync("COORD-02", PreguntaQ10Seis);

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(PerdidasDeValentina, respuesta.Respuesta);
        Assert.Contains("Datos del programa · ADM", respuesta.Citas);
        Assert.Equal(1, GuionesPorTurno.Reintentos(fabrica.Llm));
        var evento = Assert.Single(fabrica.Auditoria.Eventos);
        Assert.Equal(ResultadoAuditoria.Respondida, evento.Resultado);
        AfirmacionesDeReintento.AfirmarReintentoRegistrado(evento);
    }

    [Theory]
    [MemberData(nameof(BloqueosSinReintento))]
    [Trait("CA", "CA-21")]
    [Trait("ESC", "ESC-193")]
    [Trait("RF", "SEG-10b")]
    public async Task ESC_193f_Un_bloqueo_de_SEG_10b_hace_una_sola_llamada_y_no_lleva_reintento(string caso, string texto)
    {
        Assert.NotEmpty(caso);
        using var fabrica = new FabricaApi(llm: GuionesLlm.SinHerramientas(_ => texto), conocimientoReal: true);

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", PreguntaPromedio);

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(Textos.NegativaEstudiante, respuesta.Respuesta);
        Assert.Equal(1, fabrica.Llm.Llamadas);
        var evento = Assert.Single(fabrica.Auditoria.Eventos);
        Assert.Equal(ResultadoAuditoria.FugaBloqueada, evento.Resultado);
        Assert.False(AfirmacionesDeReintento.ReintentoRegistrado(evento));
    }

    [Fact]
    [Trait("CA", "CA-21")]
    [Trait("ESC", "ESC-193")]
    [Trait("RF", "SEG-06")]
    public async Task ESC_193f_El_403_tardio_no_se_reintenta()
    {
        using var fabrica = new FabricaApi(llm: ClienteLlmDoble.PideEstudiante("EST-004"), conocimientoReal: true);

        var respuesta = await fabrica.PreguntarCoordinadorAsync("COORD-01", "¿Qué estudiantes de mi programa perdieron materias?");

        Assert.Equal(403, respuesta.Estado);
        Assert.Equal(1, fabrica.Llm.Llamadas);
        Assert.False(AfirmacionesDeReintento.ReintentoRegistrado(Assert.Single(fabrica.Auditoria.Eventos)));
    }

    [Fact]
    [Trait("CA", "CA-21")]
    [Trait("ESC", "ESC-193")]
    [Trait("D", "D-62")]
    [Trait("RF", "SEG-13")]
    public async Task ESC_193h_Con_un_timeout_de_1_s_el_reintento_de_500_ms_se_cancela_al_llegar_a_1_s_y_se_responde_el_primer_bloqueo_en_menos_de_2_s_sin_503()
    {
        var llm = new ClienteLlmConDemoraPorTurno(TimeSpan.FromMilliseconds(750), TimeSpan.FromMilliseconds(500), "Tu promedio es 4.40.", "Tu promedio es 4.39.");
        var configuracion = new Dictionary<string, string?> { ["Limites:TimeoutLlmSegundos"] = "1" };
        using var fabrica = new FabricaApi(clienteLlm: llm, configuracion: configuracion, conocimientoReal: true);
        var reloj = Stopwatch.StartNew();

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", PreguntaPromedio);

        reloj.Stop();
        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(Textos.NoVerificable, respuesta.Respuesta);
        Assert.Empty(respuesta.Citas);
        Assert.Equal(2, llm.Llamadas);
        Assert.True(reloj.Elapsed < TimeSpan.FromSeconds(2), $"tardó {reloj.Elapsed}");
        var evento = Assert.Single(fabrica.Auditoria.Eventos);
        Assert.Equal(ResultadoAuditoria.NumeroNoVerificado, evento.Resultado);
        AfirmacionesDeReintento.AfirmarReintentoRegistrado(evento);
    }

    [Fact]
    [Trait("CA", "CA-21")]
    [Trait("ESC", "ESC-193")]
    [Trait("RF", "SEG-13")]
    public async Task ESC_193i_Sin_presupuesto_para_una_segunda_reserva_no_hay_reintento()
    {
        var configuracion = new Dictionary<string, string?> { ["Limites:PresupuestoDiarioUsd"] = "0.004", ["Llm:ReservaPorPeticionUsd"] = "0.003" };
        using var fabrica = new FabricaApi(llm: GuionesPorTurno.Texto("Tu promedio es 4.40.", "Tu promedio es 4.39."), configuracion: configuracion, variablesEntorno: EntornoSinPrecio(), conocimientoReal: true);

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", PreguntaPromedio);

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(Textos.NoVerificable, respuesta.Respuesta);
        Assert.Equal(1, fabrica.Llm.Llamadas);
        var evento = Assert.Single(fabrica.Auditoria.Eventos);
        Assert.Equal(ResultadoAuditoria.NumeroNoVerificado, evento.Resultado);
        Assert.False(AfirmacionesDeReintento.ReintentoRegistrado(evento));
    }

    [Fact]
    [Trait("CA", "CA-21")]
    [Trait("ESC", "ESC-193")]
    [Trait("RF", "SEG-13")]
    public async Task ESC_193i_Con_presupuesto_para_la_segunda_reserva_el_reintento_ocurre()
    {
        var configuracion = new Dictionary<string, string?> { ["Limites:PresupuestoDiarioUsd"] = "0.01", ["Llm:ReservaPorPeticionUsd"] = "0.003" };
        using var fabrica = new FabricaApi(llm: GuionesPorTurno.Texto("Tu promedio es 4.40.", "Tu promedio es 4.39."), configuracion: configuracion, variablesEntorno: EntornoSinPrecio(), conocimientoReal: true);

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", PreguntaPromedio);

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal("Tu promedio es 4.39.", respuesta.Respuesta);
        Assert.Equal(2, fabrica.Llm.Llamadas);
    }
}

using System.Text.RegularExpressions;
using TutorFlow.Core.Asistente;

namespace TutorFlow.Api.Tests.Contrato;

public static partial class UuidV7
{
    public static bool EsValido(string? valor) => valor is not null && FormatoRegex().IsMatch(valor);

    public static DateTimeOffset Marca(string valor) =>
        DateTimeOffset.FromUnixTimeMilliseconds(Convert.ToInt64(string.Concat(valor.AsSpan(0, 8), valor.AsSpan(9, 4)), 16));

    [GeneratedRegex("^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$")]
    private static partial Regex FormatoRegex();
}

public sealed class CorrelacionApiTests
{
    private const string ClienteCorrelacion = "00000000-0000-7000-8000-000000000001";
    private const string TraceIdDelCliente = "0af7651916cd43dd8448eb211c80319c";
    private const string TraceparentDelCliente = $"00-{TraceIdDelCliente}-b7ad6b7169203331-01";
    private const string RequestIdDelCliente = "solicitud-del-cliente-7788";
    private const int BytesDeCuerpoExcesivo = 17 * 1024;
    private static readonly TimeSpan ToleranciaMarca = TimeSpan.FromSeconds(1);

    private sealed record Captura(RespuestaApi Respuesta, EventoAuditoria Evento);

    public static TheoryData<int> Codigos => new() { 200, 400, 403, 415, 500 };

    public static TheoryData<string, string> EncabezadosDelCliente => new()
    {
        { "X-Correlation-Id", ClienteCorrelacion },
        { "X-Request-Id", RequestIdDelCliente },
        { "traceparent", TraceparentDelCliente }
    };

    private static async Task<Captura> EjecutarAsync(int codigo)
    {
        using var fabrica = codigo == 500 ? new FabricaApi(conocimiento: new ConocimientoQueExplota()) : new FabricaApi();
        fabrica.Reloj.Fijar(DateTimeOffset.UtcNow);
        var respuesta = codigo switch
        {
            400 => await fabrica.EnviarAsync(HttpMethod.Post, "/api/asistente/preguntar", """{"pregunta": """),
            403 => await fabrica.PreguntarEstudianteAsync("EST-001", "¿Cuáles son las notas de EST-002?"),
            415 => await fabrica.EnviarConTipoAsync("""{"pregunta":"hola","usuario":{"rol":"estudiante","id":"EST-001"}}""", "text/plain"),
            _ => await fabrica.PreguntarEstudianteAsync("EST-001", "¿Cuál es mi promedio ponderado del periodo?")
        };
        return new Captura(respuesta, Assert.Single(fabrica.Auditoria.Eventos));
    }

    [Theory]
    [MemberData(nameof(Codigos))]
    [Trait("CA", "CA-07")]
    [Trait("ESC", "ESC-151")]
    [Trait("ESC", "ESC-112")]
    public async Task ESC_151_Toda_respuesta_lleva_x_correlation_id_uuid_v7_igual_al_de_la_auditoria(int codigo)
    {
        var captura = await EjecutarAsync(codigo);

        Assert.Equal(codigo, captura.Respuesta.Estado);
        var encabezado = captura.Respuesta.Encabezado("X-Correlation-Id");
        Assert.True(UuidV7.EsValido(encabezado), $"X-Correlation-Id no es UUID v7: {encabezado}");
        Assert.Equal(encabezado, captura.Evento.CorrelationId);
    }

    [Theory]
    [InlineData(400)]
    [InlineData(415)]
    [InlineData(500)]
    [Trait("CA", "CA-07")]
    [Trait("ESC", "ESC-151")]
    [Trait("ESC", "ESC-112")]
    public async Task ESC_151_El_trace_id_de_todo_problem_details_es_igual_al_x_correlation_id(int codigo)
    {
        var captura = await EjecutarAsync(codigo);

        Assert.Equal(captura.Respuesta.Encabezado("X-Correlation-Id"), captura.Respuesta.Json.GetProperty("traceId").GetString());
    }

    [Theory]
    [MemberData(nameof(Codigos))]
    [Trait("CA", "CA-07")]
    [Trait("ESC", "ESC-151")]
    public async Task ESC_151_La_marca_de_tiempo_del_uuid_difiere_menos_de_un_segundo_del_evento(int codigo)
    {
        var captura = await EjecutarAsync(codigo);

        Assert.True(UuidV7.EsValido(captura.Evento.CorrelationId), $"correlationId no es UUID v7: {captura.Evento.CorrelationId}");
        var diferencia = (UuidV7.Marca(captura.Evento.CorrelationId) - captura.Evento.Timestamp).Duration();
        Assert.True(diferencia < ToleranciaMarca, $"diferencia {diferencia}");
    }

    [Fact]
    [Trait("CA", "CA-07")]
    [Trait("ESC", "ESC-151")]
    public async Task ESC_151_Los_cinco_identificadores_son_distintos_entre_si()
    {
        var identificadores = new List<string?>();
        foreach (var codigo in new[] { 200, 400, 403, 415, 500 })
        {
            identificadores.Add((await EjecutarAsync(codigo)).Respuesta.Encabezado("X-Correlation-Id"));
        }

        Assert.All(identificadores, id => Assert.True(UuidV7.EsValido(id)));
        Assert.Equal(5, identificadores.Distinct().Count());
    }

    [Fact]
    [Trait("CA", "CA-07")]
    [Trait("ESC", "ESC-151")]
    public async Task ESC_151_Salud_y_el_405_tambien_llevan_x_correlation_id_uuid_v7()
    {
        using var fabrica = new FabricaApi();

        var salud = await fabrica.EnviarAsync(HttpMethod.Get, "/api/salud", null);
        var metodo = await fabrica.EnviarAsync(HttpMethod.Put, "/api/asistente/preguntar", null);

        Assert.True(UuidV7.EsValido(salud.Encabezado("X-Correlation-Id")));
        Assert.True(UuidV7.EsValido(metodo.Encabezado("X-Correlation-Id")));
    }

    [Fact]
    [Trait("CA", "CA-07")]
    [Trait("ESC", "ESC-151")]
    public async Task ESC_151_El_413_lleva_el_mismo_uuid_en_encabezado_trace_id_y_auditoria()
    {
        using var fabrica = new FabricaApi();
        var grande = $$"""{"pregunta":"hola","usuario":{"rol":"estudiante","id":"EST-001"},"relleno":"{{new string('x', BytesDeCuerpoExcesivo)}}"}""";

        var respuesta = await fabrica.EnviarAsync(HttpMethod.Post, "/api/asistente/preguntar", grande);

        var evento = Assert.Single(fabrica.Auditoria.Eventos);
        Assert.Equal(413, respuesta.Estado);
        Assert.True(UuidV7.EsValido(respuesta.Encabezado("X-Correlation-Id")));
        Assert.Equal(respuesta.Encabezado("X-Correlation-Id"), evento.CorrelationId);
        Assert.Equal(evento.CorrelationId, respuesta.Json.GetProperty("traceId").GetString());
    }

    [Fact]
    [Trait("CA", "CA-07")]
    [Trait("ESC", "ESC-152")]
    public async Task ESC_152_El_x_correlation_id_del_cliente_se_ignora_y_no_se_registra()
    {
        using var fabrica = new FabricaApi();
        var encabezados = new Dictionary<string, string> { ["X-Correlation-Id"] = ClienteCorrelacion };

        var respuesta = await fabrica.PreguntarAsync("estudiante", "EST-001", "¿Cuál es mi promedio?", encabezados: encabezados);

        var propio = respuesta.Encabezado("X-Correlation-Id");
        Assert.True(UuidV7.EsValido(propio));
